// All queries have run upstream; read each by name and aggregate.
const leadsRes = $('New Leads (7d)').first().json.results || [];
const activeRes = $('Active Clients').first().json.results || [];
const checkinRes = $('Check-ins (7d)').first().json.results || [];
const flagRes = $('Flagged Check-ins (7d)').first().json.results || [];
const qaRes = $('Q&A Needs Human').first().json.results || [];
const leads = leadsRes.length;
const active = activeRes.length;
const checkins = checkinRes.length;
const flags = flagRes.length;
const qaOpen = qaRes.length;
const tiers = { Foundation: 20, Practice: 120, Stewardship: 240 };
let mrr = 0;
for (const r of activeRes) { const t = r.properties?.Tier?.select?.name; if (t && tiers[t]) mrr += tiers[t]; }
const adh = checkinRes.map(r => r.properties?.['Adherence %']?.number).filter(v => typeof v === 'number');
const avgAdh = adh.length ? Math.round((adh.reduce((a, b) => a + b, 0) / adh.length) * 100) : null;
const week = new Date().toISOString().slice(0, 10);
const body = [
  'Donum Dei Performance - weekly operating report (' + week + ')',
  '',
  'ACQUISITION',
  '  New leads (7d):        ' + leads,
  '',
  'ROSTER',
  '  Active clients:        ' + active,
  '  Estimated MRR:         $' + mrr,
  '',
  'ENGAGEMENT',
  '  Check-ins (7d):        ' + checkins + (active ? '  (' + Math.round((checkins / active) * 100) + '% of roster)' : ''),
  '  Avg adherence (7d):    ' + (avgAdh === null ? 'n/a' : avgAdh + '%'),
  '',
  'NEEDS YOUR ATTENTION',
  '  Flagged check-ins:     ' + flags + (flags ? '  -> review the Check-ins DB' : ''),
  '  Q&A awaiting a human:  ' + qaOpen + (qaOpen ? '  -> review the Q&A Inbox' : ''),
  '',
  'Open the hub: https://app.notion.com/p/39a21819e2ce8154acc9e34adc4ac721',
  '',
  'Donum Dei. The body is a gift. Train it accordingly.'
].join('\n');
return [{ json: { body, subject: 'DDP weekly report - ' + leads + ' leads, ' + active + ' active, $' + mrr + ' MRR' } }];
